package mz.bam.seeky.android;
import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.text.TextUtils;import android.view.*;import android.widget.*;import java.util.*;

/** Categories follow Exibir, with compact, centred content and explicit spacing. */
final class HomeCategories extends LinearLayout {
 static final String[] NAMES={"PDF","Documentos","Imagens","Vídeos","Áudio","Arquivos","Aplicações","Outros","Tudo"};
 static final int[] COLORS={0xffd94e64,0xff3878cf,0xff9959d6,0xffdf863c,0xffc94d97,0xffb38b22,0xff2e9d79,0xff78849a,0xff8c39d7};
 final MainActivity host;final int mode,columns;final List<LinearLayout> cards=new ArrayList<>();final List<TextView> titles=new ArrayList<>(),counts=new ArrayList<>();
 HomeCategories(MainActivity a){super(a);host=a;mode=Math.max(0,Math.min(5,a.viewMode));setOrientation(VERTICAL);UiSpacing.ignore(this);
  int width=Math.max(240,a.getResources().getConfiguration().screenWidthDp-28);columns=mode<=1?1:mode==2||mode==4?2:mode==5?Math.max(4,Math.min(6,width/70)):width>=620?6:width>=310&&a.getResources().getConfiguration().fontScale<=1.2f?4:3;
  Map<String,String> totals=new HashMap<>();for(String[] row:a.homeStats)totals.put(row[0],row[1]);
  for(int first=0;first<NAMES.length;first+=columns){LinearLayout row=a.row();row.setGravity(Gravity.TOP);for(int col=0;col<columns;col++){int index=first+col;LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1);if(col>0)p.leftMargin=a.dp(8);if(index>=NAMES.length){row.addView(new View(a),p);continue;}String name=NAMES[index];LinearLayout card=card(index);TextView count=counts.get(index);count.setText(a.dashboardLoaded?(name.equals("Tudo")?Long.toString(a.homeTotals[0]):totals.getOrDefault(name,"0")):"—");a.categoryCounts.put(name,count);row.addView(card,p);}LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.bottomMargin=a.dp(8);addView(row,rp);}
 }
 static String symbol(String category){switch(category){case "PDF":return "pdf";case "Documentos":return "document";case "Imagens":return "image";case "Vídeos":return "video";case "Áudio":return "audio";case "Arquivos":return "collection";case "Aplicações":return "android";case "Tudo":return "grid";default:return "dot";}}
 LinearLayout card(int index){MainActivity a=host;String name=NAMES[index];boolean list=columns==1||mode==4;int size=IconSizing.icons(a);LinearLayout card=new LinearLayout(a);cards.add(card);card.setOrientation(list?HORIZONTAL:VERTICAL);card.setGravity(Gravity.CENTER);card.setPadding(a.dp(3),a.dp(6),a.dp(3),a.dp(6));card.setBackground(a.shape(android.graphics.Color.TRANSPARENT,12));
  FrameLayout badge=new FrameLayout(a);int glyph=IconSizing.glyph(size)+10,box=AppPalette.of(a).modern?glyph+14:glyph+6;AppPalette look=AppPalette.of(a);
  if(look.modern){/* Visual moderno: ícone de linha num cartão claro e arredondado. */badge.setBackground(ThemeStyle.card(a,look,box));badge.setElevation(a.dp(1));badge.addView(new Icons(a,symbol(name),look.accent),new FrameLayout.LayoutParams(a.dp(Math.round(glyph*.62f)),a.dp(Math.round(glyph*.62f)),Gravity.CENTER));}
  else badge.addView(new CategoryIcon(a,name),new FrameLayout.LayoutParams(a.dp(glyph),a.dp(glyph),Gravity.CENTER));
  LinearLayout copy=new LinearLayout(a);copy.setOrientation(VERTICAL);copy.setGravity(Gravity.CENTER);TextView title=a.label(name.equals("Arquivos")?"ZIPs":name.equals("Aplicações")?"APKs":name,list&&mode!=4?13:12,a.text);title.setTypeface(null,Typeface.NORMAL);title.setGravity(Gravity.CENTER);title.setMaxLines(2);title.setEllipsize(TextUtils.TruncateAt.END);title.setPadding(0,a.dp(3),0,0);titles.add(title);TextView count=a.label("",list?11:10,a.muted);count.setGravity(Gravity.CENTER);count.setSingleLine(true);count.setPadding(0,a.dp(2),0,0);counts.add(count);copy.addView(title,new LinearLayout.LayoutParams(-1,-2));copy.addView(count,new LinearLayout.LayoutParams(-1,-2));if(mode==1){String[] examples={"PDF","Word · EPUB · TXT","JPG · PNG","MP4 · MKV","MP3 · WAV","ZIP · RAR","APK","Outros formatos","Todos os ficheiros"};TextView detail=a.label(examples[index],10,a.muted);detail.setGravity(Gravity.CENTER);detail.setMaxLines(1);detail.setEllipsize(TextUtils.TruncateAt.END);copy.addView(detail,new LinearLayout.LayoutParams(-1,-2));}
  if(list){card.addView(badge,new LinearLayout.LayoutParams(a.dp(box),a.dp(box)));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.leftMargin=a.dp(mode==4?4:8);cp.rightMargin=a.dp(mode==4?0:8);card.addView(copy,cp);if(columns==1){FrameLayout tail=new FrameLayout(a);tail.addView(new Icons(a,"chevron",a.accent),new FrameLayout.LayoutParams(a.dp(18),a.dp(20),Gravity.CENTER));card.addView(tail,new LinearLayout.LayoutParams(a.dp(box),a.dp(box)));}card.setMinimumHeight(a.dp((mode==1?72:mode==4?64:58)+size*2));}
  else{card.addView(badge,new LinearLayout.LayoutParams(a.dp(box),a.dp(box)));card.addView(copy,new LinearLayout.LayoutParams(-1,-2));float scale=a.getResources().getConfiguration().fontScale;card.setMinimumHeight(a.dp((mode==4?96:86)+size*4+Math.max(0,(scale-1)*34)));}
  card.setContentDescription(AppLanguage.text(a,name));card.setOnClickListener(v->a.goSearch("",name));Motion.touch(card);return card;
 }
}
